Running Python code interactively: # Let's create a minimal PKCS12 structure using Python
# PKCS12 PFX structure:
# SEQUENCE {
#   INTEGER 3  (version)
#   SEQUENCE {  (authSafe - ContentInfo)
#     OID 1.2.840.113549.1.7.1  (data)
#     [0] EXPLICIT {
#       OCTET STRING {
#         -- AuthenticatedSafe: SEQUENCE OF ContentInfo
#         SEQUENCE {
#           SEQUENCE {  (ContentInfo)
#             OID ...  (contentType)
#             [0] EXPLICIT {
#               ... (content)
#             }
#           }
#         }
#       }
#     }
#   }
# }

import struct

def encode_length(length):
    if length < 0x80:
        return bytes([length])
    elif length < 0x100:
        return bytes([0x81, length])
    elif length < 0x10000:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])
    else:
        return bytes([0x83, (length >> 16) & 0xff, (length >> 8) & 0xff, length & 0xff])

def encode_tag_length(tag, content):
    return bytes([tag]) + encode_length(len(content)) + content

def encode_sequence(content):
    return encode_tag_length(0x30, content)

def encode_integer(value):
    if value < 0x80:
        return encode_tag_length(0x02, bytes([value]))
    else:
        # Multi-byte
        result = []
        while value > 0:
            result.insert(0, value & 0xff)
            value >>= 8
        if result[0] & 0x80:
            result.insert(0, 0)
        return encode_tag_length(0x02, bytes(result))

def encode_oid(oid_str):
    """Encode an OID given as dot-separated string"""
    parts = [int(x) for x in oid_str.split('.')]
    encoded = [parts[0] * 40 + parts[1]]
    for part in parts[2:]:
        if part < 128:
            encoded.append(part)
        else:
            # Multi-byte encoding
            bytes_needed = []
            temp = part
            while temp > 0:
                bytes_needed.insert(0, temp & 0x7f)
                temp >>= 7
            for i in range(len(bytes_needed) - 1):
                bytes_needed[i] |= 0x80
            encoded.extend(bytes_needed)
    return encode_tag_length(0x06, bytes(encoded))

def encode_octet_string(content):
    return encode_tag_length(0x04, content)

def encode_explicit(tag_num, content):
    return bytes([0xa0 | tag_num]) + encode_length(len(content)) + content

# OIDs
DATA_OID = "1.2.840.113549.1.7.1"
ENCRYPTED_DATA_OID = "1.2.840.113549.1.7.6"

# Create a minimal PKCS12 structure with an empty/malformed inner content
# The inner AuthenticatedSafe has a ContentInfo with contentType OID

# Inner ContentInfo with DATA_OID and empty SafeContents
inner_safe_contents = encode_sequence(b'')  # empty SEQUENCE (no bags)
inner_content_data = encode_octet_string(inner_safe_contents)
inner_content_info = encode_sequence(
    encode_oid(DATA_OID) + 
    encode_explicit(0, inner_content_data)
)

# AuthenticatedSafe is SEQUENCE OF ContentInfo
auth_safe_content = encode_sequence(inner_content_info)

# Outer authSafe ContentInfo
auth_safe_octet_string = encode_octet_string(auth_safe_content)
auth_safe = encode_sequence(
    encode_oid(DATA_OID) + 
    encode_explicit(0, auth_safe_octet_string)
)

# PFX
pfx = encode_sequence(
    encode_integer(3) +
    auth_safe
)

print(f"Generated PKCS12 file: {len(pfx)} bytes")
print(' '.join(f'{b:02x}' for b in pfx[:80]))

with open('/workspace/poc_minimal.p12', 'wb') as f:
    f.write(pfx)

